import hashlib
import hmac
import os
import time
import unicodedata
import secrets
import threading
from collections import OrderedDict

try:
    import bcrypt
except ImportError:
    import hashlib as _h
    class bcrypt:
        @staticmethod
        def hashpw(pw, salt):
            return _h.pbkdf2_hmac('sha256', pw, salt, 310000)
        @staticmethod
        def gensalt(rounds=12):
            return os.urandom(16)
        @staticmethod
        def checkpw(pw, hashed):
            return hmac.compare_digest(bcrypt.hashpw(pw, hashed[:16]), hashed)

SECRET_KEY = os.urandom(32)

class UserStore:
    """Thread-safe user storage with Unicode-aware username handling."""

    def __init__(self):
        self._lock = threading.Lock()
        self._users = {}  # normalized_username -> {password_hash, role, display_name}

    def _normalize_username(self, username):
        """Normalize username for consistent lookup.
        Uses NFKC normalization and case folding for Unicode safety.
        """
        # Strip leading/trailing whitespace
        username = username.strip()
        # Apply Unicode NFKC normalization
        username = unicodedata.normalize('NFKC', username)
        # Case fold for case-insensitive comparison
        username = username.casefold()
        return username

    def register(self, username, password, role=0):
        """Register a new user. Returns True on success, False if exists."""
        if not username or not password:
            return False
        if len(username) > 64 or len(password) > 72:
            return False

        # Validate username contains only allowed characters
        normalized = self._normalize_username(username)
        if not normalized:
            return False

        with self._lock:
            if normalized in self._users:
                return False

            salt = bcrypt.gensalt(rounds=12)
            pw_hash = bcrypt.hashpw(password.encode('utf-8'), salt)
            self._users[normalized] = {
                'password_hash': pw_hash,
                'role': max(0, min(3, int(role))),
                'display_name': username.strip()
            }
            return True

    def authenticate(self, username, password):
        """Authenticate user. Returns (normalized_name, role) or None."""
        if not username or not password:
            return None

        normalized = self._normalize_username(username)

        with self._lock:
            user = self._users.get(normalized)
            if user is None:
                # Constant-time fake check to prevent user enumeration
                bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(rounds=12))
                return None

            if bcrypt.checkpw(password.encode('utf-8'), user['password_hash']):
                return (normalized, user['role'])
            return None

    def get_role(self, username):
        """Get user's current role."""
        normalized = self._normalize_username(username)
        with self._lock:
            user = self._users.get(normalized)
            return user['role'] if user else None

    def update_role(self, username, new_role):
        """Update user's role (admin operation)."""
        normalized = self._normalize_username(username)
        with self._lock:
            if normalized in self._users:
                self._users[normalized]['role'] = max(0, min(3, int(new_role)))
                return True
            return False


class TokenManager:
    """Manages authentication tokens with HMAC-SHA256."""

    def __init__(self, secret_key, max_tokens=10000):
        self._key = secret_key
        self._lock = threading.Lock()
        self._tokens = OrderedDict()
        self._max = max_tokens

    def _compute_mac(self, data):
        return hmac.new(self._key, data, hashlib.sha256).digest()

    def issue_token(self, username, role, ttl=3600):
        """Issue a new token for the given user."""
        token_id = secrets.token_bytes(16)
        issued_at = int(time.time())
        expires_at = issued_at + ttl

        # Token payload: token_id(16) + username_utf8 + null + role(1) + issued(8) + expires(8)
        username_bytes = username.encode('utf-8')
        payload = token_id + username_bytes + b'\x00' + bytes([role & 0xFF]) + \
                  issued_at.to_bytes(8, 'big') + expires_at.to_bytes(8, 'big')

        mac = self._compute_mac(payload)
        token = payload + mac

        with self._lock:
            if len(self._tokens) >= self._max:
                self._tokens.popitem(last=False)
            self._tokens[token_id] = {
                'username': username,
                'role': role,
                'expires_at': expires_at,
                'token': token
            }

        return token

    def validate_token(self, token_bytes):
        """Validate token and return (username, role) or None."""
        if not token_bytes or len(token_bytes) < 58:  # min: 16+1+1+1+8+8+32 = 67? no, 16+0+1+1+8+8+32=66 min
            return None

        # Split MAC
        payload = token_bytes[:-32]
        provided_mac = token_bytes[-32:]

        # Verify MAC
        expected_mac = self._compute_mac(payload)
        if not hmac.compare_digest(expected_mac, provided_mac):
            return None

        # Parse payload
        token_id = payload[:16]
        rest = payload[16:]

        # Find null separator for username
        null_idx = rest.find(b'\x00')
        if null_idx < 0:
            return None

        username = rest[:null_idx].decode('utf-8', errors='strict')
        after_null = rest[null_idx + 1:]

        if len(after_null) != 17:  # 1 + 8 + 8
            return None

        role = after_null[0]
        issued_at = int.from_bytes(after_null[1:9], 'big')
        expires_at = int.from_bytes(after_null[9:17], 'big')

        # Check expiration
        now = int(time.time())
        if now > expires_at:
            with self._lock:
                self._tokens.pop(token_id, None)
            return None

        # Check token exists in store
        with self._lock:
            stored = self._tokens.get(token_id)
            if stored is None:
                return None

        if role > 3:
            return None

        return (username, role)

    def revoke_token(self, token_bytes):
        """Revoke a token."""
        if not token_bytes or len(token_bytes) < 48:
            return False
        token_id = token_bytes[:16]
        with self._lock:
            return self._tokens.pop(token_id, None) is not None


class PasswordResetManager:
    """Handles password reset tokens."""

    def __init__(self, user_store):
        self._user_store = user_store
        self._lock = threading.Lock()
        self._reset_tokens = {}  # reset_code -> {username, expires_at}

    def request_reset(self, username):
        """Generate a password reset code for the given username."""
        # Normalize the username for lookup
        normalized = self._user_store._normalize_username(username)

        # Check user exists
        if self._user_store.get_role(normalized) is None:
            return None

        # Generate reset code
        reset_code = secrets.token_hex(32)
        expires_at = int(time.time()) + 900  # 15 minutes

        with self._lock:
            self._reset_tokens[reset_code] = {
                'username': username,  # Store the ORIGINAL username, not normalized
                'expires_at': expires_at
            }

        return reset_code

    def execute_reset(self, reset_code, new_password):
        """Execute a password reset using the provided code."""
        if not reset_code or not new_password:
            return False
        if len(new_password) > 72:
            return False

        with self._lock:
            entry = self._reset_tokens.pop(reset_code, None)

        if entry is None:
            return False

        if int(time.time()) > entry['expires_at']:
            return False

        # Use the stored username to find the account
        username = entry['username']
        normalized = self._user_store._normalize_username(username)

        with self._user_store._lock:
            if normalized not in self._user_store._users:
                return False

            salt = bcrypt.gensalt(rounds=12)
            pw_hash = bcrypt.hashpw(new_password.encode('utf-8'), salt)
            self._user_store._users[normalized]['password_hash'] = pw_hash
            return True


# Application setup
user_store = UserStore()
token_mgr = TokenManager(SECRET_KEY)
reset_mgr = PasswordResetManager(user_store)


def handle_register(username, password, role=0):
    """Handle user registration."""
    return user_store.register(username, password, role)


def handle_login(username, password):
    """Handle login, return token or None."""
    result = user_store.authenticate(username, password)
    if result is None:
        return None
    normalized, role = result
    return token_mgr.issue_token(normalized, role)


def handle_request(token_bytes, required_role=0):
    """Authorize a request. Returns (username, role) or None."""
    result = token_mgr.validate_token(token_bytes)
    if result is None:
        return None
    username, role = result
    if role >= required_role:
        return (username, role)
    return None


def handle_password_reset_request(username):
    """Request a password reset. Returns reset code (in real app, sent via email)."""
    return reset_mgr.request_reset(username)


def handle_password_reset(reset_code, new_password):
    """Execute password reset."""
    return reset_mgr.execute_reset(reset_code, new_password)
